// PayuniSellerFacingErrorLabel 回傳 value 對應的中文標籤。未登錄的值原樣回傳：
// 顯示原始碼值仍看得出發生了什麼，回空字串則會在畫面上留下一個無法追查的空格。
func PayuniSellerFacingErrorLabel(value string) string {
	if l, ok := payuniSellerFacingErrorLabels[value]; ok {
		return l
	}
	return value
}

